$p=$payload;$p['route']['variants'][0]['stop_refs'][]='RX';$r=stti_v070_relation_review($p,$resolver);$ok((bool)array_filter($r['errors'],fn($x)=>str_contains($x,'unknown stop')),'unknown stop ref errors');
$ok(stti_v070_hotel_link_state('sth-000123')['hotel_id']==='STH-000123','hotel stable ID uppercases');$ok(stti_v070_hotel_link_state('STH-123')['status']==='invalid','hotel stable ID requires six digits');
$p=$payload;$p['stays']['hotels'][0]=['relation_id'=>'H1','mode'=>'unresolved','unresolved_name'=>'Source Hotel','review_status'=>'confirmed'];$r=stti_v070_relation_review($p,$resolver);$ok($r['normalized']['hotel_relations'][0]['unresolved_name']==='Source Hotel','unresolved source hotel preserved');$ok(!$r['ready_for_editorial_approval'],'unresolved hotel blocks approval');
