$p=$payload;$p['stays']['hotels'][]=['relation_id'=>'H2','mode'=>'hotel_intelligence','hotel_stable_id'=>'STH-000002','option_group_id'=>'HG1','selection_status'=>'selected','review_status'=>'confirmed'];$r=stti_v070_relation_review($p,$resolver);$ok((bool)array_filter($r['errors'],fn($x)=>str_contains($x,'more than one selected')),'duplicate selected option group errors');
$p=$payload;$p['route']['variants'][]=['variant_id'=>'V2','role'=>'primary','review_status'=>'confirmed'];$r=stti_v070_relation_review($p,$resolver);$ok((bool)array_filter($r['errors'],fn($x)=>str_contains($x,'More than one active')),'multiple primary variants error');
$p=$payload;$p['stays']['hotels'][]=['relation_id'=>'H2','mode'=>'unresolved','unresolved_name'=>'Rejected','review_status'=>'rejected'];$r=stti_v070_relation_review($p,$resolver);$ok($r['ready_for_editorial_approval'],'unreferenced rejected evidence does not block');
$r=stti_v070_relation_review($legacy,$resolver);$ok(!$r['errors'],'legacy stops need no IDs until referenced');
$old=[['variant_id'=>'V1','review_status'=>'pending','reviewed_by'=>999,'reviewed_at'=>'old']];$new=[['variant_id'=>'V1','review_status'=>'confirmed','reviewed_by'=>999,'reviewed_at'=>'forged']];$s=stti_v070_stamp_review_transitions(stti_v070_normalize_route_variants($new),stti_v070_normalize_route_variants($old),'variant_id');$ok($s[0]['reviewed_by']===42,'client reviewer replaced by server');$ok($s[0]['reviewed_at']==='2026-09-14 16:00:00','server review timestamp set');
